export function getFaixaEtaria(idade: number): FaixaEtaria | null {
  if (idade>=21&&idade<=25) return '21 - 25';
  if (idade>=26&&idade<=30) return '26 - 30';
  if (idade>=31&&idade<=35) return '31 - 35';
  if (idade>=36&&idade<=40) return '36 - 40';
  if (idade>=41&&idade<=45) return '41 - 45';
  if (idade>=46&&idade<=50) return '46 - 50';
  if (idade>=51&&idade<=55) return '51 - 55';
  if (idade>=56&&idade<=60) return '56 - 60';
  return null;
}
export function buscarLinhaTabela(renda: number, faixaEtaria: FaixaEtaria): LinhaTabela | null {
  const linhas = TABELA_FINANCIAMENTO[faixaEtaria];
  if (!linhas||linhas.length===0) return null;
  let melhor: LinhaTabela | null = null;
  for (const linha of linhas) { if (linha.renda<=renda) melhor=linha; else break; }
  return melhor??linhas[0];
}
